using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class SpatialFinish {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static bool Lab(Vector3 p)=>(new Vector2(p.x+15,p.z+10)).magnitude<10.1f;
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var fresh=root.Find("Spatial_DestinationGuidance");var old=root.Find("Remaining_DestinationGuidance");if(fresh.Cast<Transform>().Any(t=>t.name.StartsWith("SF_RetainedLab_")))throw new Exception("Already finished; regenerate owned guides first");int retained=0;
 // Keep the approved lab's actual guide triangles, UVs and materials, including arrows.
 foreach(var f in fresh.GetComponentsInChildren<MeshFilter>()){if(f.name=="SF_C01_LocalJoin"){f.gameObject.SetActive(false);continue;}var m=f.sharedMesh;string path=AssetDatabase.GetAssetPath(m);if(!Path.GetFileName(path).StartsWith("SF_"))continue;var vs=m.vertices;var ts=m.triangles;var keep=new List<int>();for(int i=0;i<ts.Length;i+=3){var c=(vs[ts[i]]+vs[ts[i+1]]+vs[ts[i+2]])/3;if(!Lab(f.transform.TransformPoint(c)))keep.AddRange(new[]{ts[i],ts[i+1],ts[i+2]});}m.triangles=keep.ToArray();m.RecalculateBounds();EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);}
 foreach(var f in old.GetComponentsInChildren<MeshFilter>(true)){var src=f.sharedMesh;var vs=src.vertices.Select(v=>f.transform.TransformPoint(v)).ToArray();var ts=src.triangles;var keep=new List<int>();for(int i=0;i<ts.Length;i+=3)if(Lab((vs[ts[i]]+vs[ts[i+1]]+vs[ts[i+2]])/3))keep.AddRange(new[]{ts[i],ts[i+1],ts[i+2]});if(keep.Count==0)continue;var m=UnityEngine.Object.Instantiate(src);m.name="SF_RetainedLab_"+f.name;m.vertices=vs;m.triangles=keep.ToArray();m.RecalculateBounds();string path="Assets/Afrer_Seconds/05.Model/Environment/B5/"+m.name+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing){EditorUtility.CopySerialized(m,existing);UnityEngine.Object.DestroyImmediate(m);m=existing;EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);}else AssetDatabase.CreateAsset(m,path);var g=new GameObject(m.name);g.transform.SetParent(fresh,false);g.AddComponent<MeshFilter>().sharedMesh=m;var rr=g.AddComponent<MeshRenderer>();rr.sharedMaterials=f.GetComponent<Renderer>().sharedMaterials;rr.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;retained+=keep.Count/3;}
 var desks=root.Find("B5_Spatial_Refinement/N01").Cast<Transform>().Where(t=>t.name.Contains("CentralOperatorDesk")).ToArray();int index=0;int[][] screens={new[]{1,8},new[]{2,3},new[]{5,6},new[]{7,9},new[]{10,15},new[]{16,17}};foreach(var desk in desks){foreach(var rr in desk.GetComponentsInChildren<Renderer>()){var ms=rr.sharedMaterials;int slot=0;for(int i=0;i<ms.Length;i++)if(ms[i].name.StartsWith("RD_Display_")){var path="Assets/Afrer_Seconds/05.Model/Props/B5/Materials/RD_Display_"+screens[index][slot++%2].ToString("00")+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m)throw new Exception(path);ms[i]=m;}rr.sharedMaterials=ms;PrefabUtility.RecordPrefabInstancePropertyModifications(rr);}index++;}
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{retainedLabGuideTriangles=retained,operatorDesks=index,staticDisplayRoles=12};File.WriteAllText(R+"/Docs/검수/2026-11-08_B5_SpatialRefinement/finish.json",JsonConvert.SerializeObject(result));return result;}}
